# английские подписи для экрана у языков, чей шрифт на экране не нарисует: «Помпа» и «Кулер CPU» совпадают с названиями датчиков в списке
SCREEN_EN = {"Помпа": "Pump", "Кулер CPU": "CPU Fan", "Кулер GPU": "GPU Fan", "Жидкость": "Coolant", "Сеть ↓": "Net ↓", "Сеть ↑": "Net ↑",
             "Корпус": "Case", "GPU Вт": "GPU W", "GPU МГц": "GPU MHz", " об/м": " rpm", " Вт": " W", " МГц": " MHz", " МБ/с": " MB/s",
             "МБ/с": "MB/s", "КБ/с": "KB/s"}


def main():
    out_dir = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "locales")
    os.makedirs(out_dir, exist_ok=True)
    for i, code in enumerate(CODES, start=1):
        cat = {}
        for row in ROWS:
            assert len(row) == len(CODES) + 1, row[0]
            cat[row[0]] = row[i]
        if code in CJK:
            cat.update({"screen:" + k: v for k, v in SCREEN_EN.items()})
        with open(os.path.join(out_dir, f"{code}.json"), "w", encoding="utf-8") as f:
            json.dump(cat, f, ensure_ascii=False, indent=1)
    print("языков:", len(CODES), "строк:", len(ROWS))


if __name__ == "__main__":
    main()
